# Generated by Claudian.
"""Command router — dispatches a spoken utterance to the right skill.

Four tiers, cheapest first:

  1. SkillRegistry regex match. Free, ~5ms. Wins outright at >=0.85.
  2. Local intent model (ai/intent_classifier_local). ~0.13ms, but only
     answers above its confidence gate; otherwise it abstains.
  3. Groq LLM classifier. 350-500ms network round trip, highest accuracy.
  4. The `conversation` skill, which always matches, as the catch-all.

Tier 2 exists because tier 3 was being paid on every ambiguous utterance
purely to choose a skill. On hand-written unseen phrasings the local model
absorbs ~56% of that traffic at 97% accuracy, and defers the rest.
"""

from ai.intent_classifier import IntentClassifier
from ai.intent_classifier_local import get_local_classifier
from memory import get_memory
from multitasking.async_executor import run_in_thread
from skills._base import SkillResult
from skills._registry import get_registry
from utils.logger import get_logger
from utils.latency_profiler import get_profiler

logger = get_logger(__name__)

# Skills that change something. Getting one of these wrong is visible and
# annoying; getting an informational skill wrong just wastes a sentence.
ACTION_SKILLS = frozenset({
    "open_app", "close_app", "open_website", "music", "volume", "brightness",
    "mute", "screenshot", "lock_screen", "empty_trash", "whatsapp_send",
    "shutdown_system", "restart_system", "shutdown_jarvis", "remember",
})

# Confidence an action needs when the utterance arrived WITHOUT a wake word.
# Saying "jarvis" is itself evidence the user is addressing the assistant;
# a conversation-window follow-up has no such evidence, so the bar is higher.
FOLLOWUP_ACTION_CONFIDENCE = 0.90

# Which tiers may take an action on a follow-up.
#
# The LLM is excluded, because its confidence is SELF-REPORTED and measurably
# unreliable here: on the real utterance "that is open, spotify." — the user
# remarking that Spotify was already open — it returned open_app at 0.95 and
# relaunched the app. No threshold fixes that, because the number itself is
# wrong.
#
# The regex registry scores by literal pattern match, and the local model's
# gate was calibrated against held-out data. Both are evidence about the
# utterance. The LLM's number is the LLM's opinion of itself.
FOLLOWUP_TRUSTED_SOURCES = frozenset({"regex", "local"})


class CommandRouter:
    """Backward-compat name — the old `CommandRouter` is now this dispatcher."""

    def __init__(self, conversation_engine=None):
        # `conversation_engine` is accepted for API compat with the old router
        # but ignored here: the `conversation` skill owns its own engine.
        self._registry = get_registry()
        self._classifier = IntentClassifier(self._registry)
        self._memory = get_memory()

    async def route(self, text: str, from_followup: bool = False) -> tuple[str, bool, bool, object]:
        """Run the best skill for `text`.

        Returns (reply_text, should_shutdown, already_spoken, confirm).
        `from_followup` is True when the utterance was picked up during the
        conversation window rather than after a wake word. Side-effecting
        skills then need higher confidence, and below it fall through to a
        confirmation question instead of acting.

        `confirm` is a PendingAction when the skill wants approval before
        doing anything irreversible — see core/confirmation.py."""
        profiler = get_profiler()

        # 1. Local match via skill registry
        profiler.start_stage("skill_match")
        skill, match = self._registry.match(text)
        profiler.end_stage("skill_match")

        # 2. Local model fast path.
        #
        # Sits between the regex registry and the Groq fallback. It answers in
        # ~0.13ms versus a 350-500ms network round trip, but only when its
        # softmax confidence clears the gate chosen at training time. Below
        # that it returns None and we fall through to the LLM unchanged.
        #
        # Measured on hand-written unseen phrasings: 56% of otherwise
        # LLM-bound traffic handled locally at 97% accuracy.
        if not self._registry.is_high_confidence(match):
            local = get_local_classifier()
            if local.available:
                profiler.start_stage("local_classify")
                predicted, confidence = local.predict_gated(text)
                profiler.end_stage("local_classify")

                if predicted and self._action_allowed(
                    predicted, confidence, from_followup, source="local"
                ):
                    local_skill = self._registry.by_name(predicted)
                    if local_skill is not None:
                        # The model gives us a skill name but no entities, so
                        # let the skill parse its own slots out of the text.
                        own = local_skill.match(text)
                        entities = own.entities if own else {}
                        logger.info(
                            f"Local model: {predicted} (conf {confidence:.2f}) "
                            f"entities={entities}"
                        )
                        profiler.start_stage("skill_execute")
                        result = await local_skill.run(text, entities)
                        profiler.end_stage("skill_execute")
                        await self._log(text, result, local_skill.name,
                                        source="local", confidence=confidence)
                        return (result.text, result.should_shutdown,
                                result.already_spoken, result.confirm)

        # 3. LLM fallback if neither the registry nor the local model was sure
        if not self._registry.is_high_confidence(match):
            profiler.start_stage("llm_classify")
            llm_pick = await run_in_thread(self._classifier.classify, text)
            profiler.end_stage("llm_classify")

            if llm_pick and self._action_allowed(
                llm_pick["intent"], float(llm_pick.get("confidence", 0.7)),
                from_followup, source="llm",
            ):
                llm_skill = self._registry.by_name(llm_pick["intent"])
                if llm_skill is not None:
                    skill = llm_skill
                    match_entities = llm_pick.get("entities", {})
                    logger.info(
                        f"LLM classified: {llm_pick['intent']} "
                        f"(conf {llm_pick.get('confidence', 0.7):.2f}) "
                        f"entities={match_entities}"
                    )
                    profiler.start_stage("skill_execute")
                    result = await skill.run(text, match_entities)
                    profiler.end_stage("skill_execute")
                    # Log here too — this early return previously skipped it,
                    # so anything routed by the LLM never reached memory and
                    # was invisible to `recall` and the end-of-day recap.
                    await self._log(text, result, skill.name, source="llm",
                                    confidence=float(llm_pick.get("confidence", 0.7)))
                    return (result.text, result.should_shutdown,
                            result.already_spoken, result.confirm)

        # 4. Run whatever we got from the registry (fall back to conversation
        #    if somehow nothing matched — shouldn't happen since the
        #    conversation skill always matches at confidence 0.05)
        if skill is None:
            skill = self._registry.by_name("conversation")
            match = None

        if not self._action_allowed(
            skill.name, match.confidence if match else 0.0, from_followup,
            source="regex",
        ):
            return self._ask_instead(skill, text, match)

        entities = match.entities if match else {}
        logger.info(
            f"Skill: {skill.name} "
            f"(conf {match.confidence if match else 0:.2f}) "
            f"entities={entities}"
        )
        profiler.start_stage("skill_execute")
        result: SkillResult = await skill.run(text, entities)
        profiler.end_stage("skill_execute")

        await self._log(text, result, skill.name, source="regex",
                        confidence=match.confidence if match else 0.0)
        return (result.text, result.should_shutdown,
                result.already_spoken, result.confirm)

    @staticmethod
    def _action_allowed(skill_name: str, confidence: float,
                        from_followup: bool, source: str = "regex") -> bool:
        """Whether a side-effecting skill may run on this evidence."""
        if not from_followup:
            return True
        if skill_name not in ACTION_SKILLS:
            return True   # informational skills are cheap to get wrong
        if source not in FOLLOWUP_TRUSTED_SOURCES:
            return False  # see FOLLOWUP_TRUSTED_SOURCES
        return confidence >= FOLLOWUP_ACTION_CONFIDENCE

    def _ask_instead(self, skill, text: str, match):
        """Confirm rather than act on a weakly-evidenced follow-up.

        Astra's design note applies here: ask a focused question when the
        answer could change the outcome, and proceed on sensible assumptions
        otherwise. Re-opening an app the user was merely talking about is
        exactly the case worth one short question.
        """
        from core.confirmation import PendingAction

        entities = match.entities if match else {}
        conf = match.confidence if match else 0.0
        logger.info(
            f"Follow-up action withheld: {skill.name} at {conf:.2f} "
            f"(needs {FOLLOWUP_ACTION_CONFIDENCE})"
        )

        async def _do() -> str:
            result = await skill.run(text, entities)
            return result.text

        return (
            f"Did you want me to {skill.description[0].lower()}{skill.description[1:]}?",
            False,
            False,
            PendingAction(description=f"{skill.name} ({text})", run=_do),
        )

    async def _log(self, text: str, result: SkillResult, skill_name: str,
                   source: str = "", confidence: float = 0.0) -> None:
        """Fire-and-forget memory write. Never let logging break a reply.

        `source`/`confidence` record which tier decided the route. Only
        high-confidence 'regex' rows are later used as training labels —
        training on the model's own predictions would just reinforce its
        mistakes.
        """
        try:
            await run_in_thread(
                self._memory.log_event, text, result.text, skill_name,
                source, confidence,
            )
        except Exception as e:
            logger.debug(f"memory.log_event failed: {e}")
